import sys
import json
import os

def get_date(val):
    if not val:
        return None
    return str(val)[:10]

def get_amount(val):
    if val is None:
        return None
    return str(val)

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, 'usaspending_awards.json')
    awards_data = []
    if os.path.exists(awards_path):
        with open(awards_path, 'r') as f:
            awards_data = json.load(f)

    awards_by_id = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            if award_id not in awards_by_id:
                awards_by_id[award_id] = []
            awards_by_id[award_id].append(award)

    results = {}

    for pair in manifest.get("pairs", []):
        rule_id, entity_id = pair.split("::")
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        records = awards_by_id.get(entity_id, [])

        for fact in facts:
            extracted_values = set()

            for record in records:
                val = None
                if fact == "performance start":
                    pop = record.get("period_of_performance") or {}
                    val = get_date(pop.get("start_date"))
                elif fact == "performance end":
                    pop = record.get("period_of_performance") or {}
                    val = get_date(pop.get("end_date"))
                elif fact == "amount obligated":
                    val = get_amount(record.get("total_obligation"))
                elif fact == "potential value":
                    val = get_amount(record.get("base_and_all_options"))

                if val is not None:
                    extracted_values.add(val)

            if len(extracted_values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(extracted_values) == 1:
                pair_result[fact] = [list(extracted_values)[0], "usaspending_awards"]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

