import sys
import json
import os

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, 'usaspending_awards.json')
    awards_data = []
    if os.path.exists(awards_path):
        with open(awards_path, 'r') as f:
            awards_data = json.load(f)

    # Group awards by generated_unique_award_id
    entities = {}
    for award in awards_data:
        entity_id = award.get("generated_unique_award_id")
        if entity_id:
            if entity_id not in entities:
                entities[entity_id] = []
            entities[entity_id].append(award)

    results = {}
    for pair in manifest.get("pairs", []):
        rule_id, entity = pair.split("::")
        facts = manifest.get("facts", {}).get(rule_id, [])

        pair_result = {}
        for fact in facts:
            values = set()
            if entity in entities:
                for award in entities[entity]:
                    val = None
                    if rule_id == "usa.period_3y":
                        pop = award.get("period_of_performance")
                        if isinstance(pop, dict):
                            if fact == "performance start":
                                val = pop.get("start_date")
                            elif fact == "performance end":
                                val = pop.get("end_date")
                    elif rule_id == "usa.obligated_95":
                        if fact == "amount obligated":
                            val = award.get("total_obligation")
                        elif fact == "potential value":
                            val = award.get("base_and_all_options")

                    if val is not None and val != "":
                        if rule_id == "usa.period_3y":
                            # Format date as YYYY-MM-DD
                            val_str = str(val)[:10]
                            values.add(val_str)
                        elif rule_id == "usa.obligated_95":
                            # Format amount as decimal string
                            val_str = str(val)
                            values.add(val_str)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], "usaspending_awards"]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

